head.script:
document.addEventListener('DOMContentLoaded', function () {
  document.querySelectorAll('a[href*="/search/label/"]').forEach(function (a) {
    var url = a.getAttribute('href');
    if (url) {
      if (url.indexOf('max-results') === -1) {
        a.setAttribute('href', url + '?max-results=9');
      }
    }
  });
  document.querySelectorAll('a[href*="max-results="]').forEach(function (a) {
    var url = a.getAttribute('href');
    if (url) {
      a.setAttribute('href', url.replace(/max-results=\d+/, 'max-results=9'));
    }
  });
});

