(function(){
  var el = document.getElementById('label-total-count');
  if(!el) return;
  var m = window.location.pathname.match(/\/search\/label\/(.+)/);
  if(!m) return;
  var url = window.location.origin + '/feeds/posts/default/-/' + m[1] + '?alt=json&max-results=1';
  fetch(url).then(function(r){ return r.json(); }).then(function(d){
    var t = d.feed.openSearch$totalResults && d.feed.openSearch$totalResults.$t;
    if(t) el.textContent = t + ' Posts';
  }).catch(function(){});
})();
