b:includable.script:
//
(function(){
  // ── config ──────────────────────────────────────────────
  var PER_PAGE   = 9;
  var MAX_DEPTH  = 20;                  // #6: 재귀 깊이 제한
  var CACHE_KEY  = 'apl_cache_v1';
  var CACHE_TTL  = 30 * 60 * 1000;     // #3: 30분 캐시

  // ── DOM ─────────────────────────────────────────────────
  var loadEl = document.getElementById('apl-loading');
  var contEl = document.getElementById('apl-content');
  var headEl = document.getElementById('apl-header');
  if(!contEl) return;

  // ── feed URL ─────────────────────────────────────────────
  var base       = window.location.origin;
  var labelMatch = window.location.pathname.match(/\/search\/label\/(.+)/);
  var labelSeg   = labelMatch ? labelMatch[1] : null;
  var feedBase   = labelSeg
    ? base + '/feeds/posts/default/-/' + labelSeg + '?alt=json'
    : base + '/feeds/posts/default?alt=json';
  if(labelSeg && headEl)
    headEl.textContent = '\uD83D\uDCCB ' + decodeURIComponent(labelSeg).replace(/\+/g,' ') + ' Posts';

  // ── state ────────────────────────────────────────────────
  var all     = [];
  var curPage = 1;

  // ── #8: 공통 스타일 상수 ─────────────────────────────────
  var S_CARD = 'position:relative;display:flex;flex-direction:column;justify-content:space-between;'
             + 'background:#ffffff;border-radius:8px;box-shadow:0 1px 4px rgba(0,0,0,.1);'
             + 'overflow:hidden;border-top:3px solid #1d89cf;transition:box-shadow .2s,background .2s';
  var S_BTN  = 'font-size:12px;font-weight:700;border:none;border-radius:5px;padding:5px 11px;cursor:pointer;transition:background .15s;';
  var S_ON   = S_BTN + 'background:rgba(20,55,100,0.75);color:#7ec8f4;';
  var S_ACT  = S_BTN + 'background:#1d89cf;color:#fff;';
  var S_OFF  = S_BTN + 'background:rgba(15,30,55,0.4);color:#334466;cursor:default;';

  // ── pinned ad card (always first) ───────────────────────
  var AD_URL    = 'https://www.shippauljobs.com/p/advertisement-26-01.html';
  var ORDER_URL = 'https://www.coupang.com/?src=1139000&amp;spec=10799999&amp;addtag=900&amp;ctag=HOME&amp;lptag=AF0526816&amp;itime=20260504235421&amp;pageType=HOME&amp;pageValue=HOME&amp;wPcid=17421017702267830069309&amp;wRef=ads-partners.coupang.com&amp;wTime=20260504235421&amp;redirect=landing&amp;traceid=V0-541-f1c1c0fa2d1581c7-I476010&amp;mcid=6654bddc6f39470590300404e9a77e0d&amp;placementid=&amp;campaignid=&amp;contentcategory=&amp;imgsize=&amp;pageid=&amp;tsource=&amp;deviceid=&amp;contenttype=&amp;token=&amp;impressionid=20260504235402145073137739&amp;subid=&amp;campaigntype=&amp;contentkeyword=&amp;newssource=&amp;subparam=';
  var adCard = '<div style="' + S_CARD + ';border-top-color:#e8231a" data-card>'
    + '<span style="position:absolute;top:8px;left:8px;background:#e8231a;color:#fff;font-size:9px;font-weight:800;min-width:20px;height:20px;border-radius:10px;display:flex;align-items:center;justify-content:center;padding:0 6px;line-height:1;z-index:2;letter-spacing:0.4px">AD</span>'
    + '<div style="padding:10px 14px 8px 38px;">'
    + '<div style="font-size:12.5px;font-weight:800;color:#0a2342;line-height:1.3;">Purchase Products at Coupang!</div>'
    + '</div>'
    + '<div style="width:100%;height:165px;overflow:hidden;position:relative;background:#f5f5f5;border-bottom:1px solid #e0eaf4;">'
    + '<div id="cp-preview-host" style="position:absolute;top:0;left:50%;width:600px;height:460px;transform:translateX(-50%) scale(0.35);transform-origin:top center;overflow:hidden;"></div>'
    + '<a href="' + ORDER_URL + '" target="_blank" rel="noopener sponsored" style="position:absolute;top:0;left:0;width:100%;height:100%;z-index:10;display:block;cursor:pointer;" title="Shop at Coupang"></a>'
    + '</div>'
    + '<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 14px 12px;border-top:1px solid #e0eaf4;">'
    + '<div style="display:flex;gap:6px;">'
    + '<a href="' + AD_URL + '" style="font-size:11px;color:#fff;background:#e8231a;padding:4px 11px;border-radius:5px;text-decoration:none;font-weight:700;letter-spacing:0.4px;" target="_blank" rel="noopener">VISIT &#8594;</a>'
    + '<a href="' + ORDER_URL + '" style="font-size:11px;color:#fff;background:#c8121a;padding:4px 11px;border-radius:5px;text-decoration:none;font-weight:700;letter-spacing:0.4px;" target="_blank" rel="noopener sponsored">Order Now &#128722;</a>'
    + '</div>'
    + '</div>'
    + '</div>';

  // ── #4: XSS 이스케이프 ──────────────────────────────────
  function esc(s){
    return String(s)
      .replace(/&/g,'&amp;').replace(/</g,'&lt;')
      .replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  // ── #3: 캐시 ────────────────────────────────────────────
  function loadCache(){
    try{
      var raw = localStorage.getItem(CACHE_KEY);
      if(!raw) return null;
      var c = JSON.parse(raw);
      if(Date.now() - c.ts > CACHE_TTL) return null;
      if((c.label||null) !== (labelSeg||null)) return null;
      return c.items;
    }catch(e){ return null; }
  }
  function saveCache(items){
    try{ localStorage.setItem(CACHE_KEY, JSON.stringify({ts:Date.now(), label:labelSeg||null, items:items})); }
    catch(e){}
  }

  // ── #6: 재귀 fetch (깊이 제한) ───────────────────────────
  function fetchPage(url, depth){
    if(depth > MAX_DEPTH){ render(); return; }
    fetch(url)
      .then(function(r){
        if(!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function(d){
        (d.feed.entry || []).forEach(function(e){
          var href = '';
          (e.link || []).forEach(function(l){ if(l.rel === 'alternate') href = l.href; });
          var thumb = '';
          if(e.media$thumbnail && e.media$thumbnail.url)
            thumb = e.media$thumbnail.url.replace(/\/s\d+(-c)?\//, '/s400/');
          all.push({
            title : e.title.$t,
            url   : href,
            date  : (e.published.$t || '').substring(0,10),
            labels: (e.category || []).map(function(c){ return c.term; }),
            image : thumb
          });
        });
        var next = null;
        (d.feed.link || []).forEach(function(l){ if(l.rel === 'next') next = l.href; });
        if(next){ fetchPage(next, depth + 1); }
        else{ saveCache(all); render(); }
      })
      .catch(function(err){
        console.warn('[apl] fetch error:', err);
        if(all.length > 0){
          // 일부 페이지까지 수집된 데이터가 있으면 그대로 렌더
          saveCache(all);
          render();
        } else {
          // 첫 fetch 자체가 실패한 경우만 에러 표시
          if(loadEl){
            loadEl.innerHTML = '\u26A0\uFE0F Failed to load posts. '
              + '<button onclick="location.reload()" style="font-size:11px;padding:3px 10px;border:1px solid #c0392b;border-radius:4px;background:#fff;color:#c0392b;cursor:pointer;margin-left:6px">Retry</button>';
            loadEl.style.color = '#c0392b';
          }
        }
      });
  }

  // ── render page ──────────────────────────────────────────
  function renderPage(page){
    var totalPages = Math.ceil(all.length / PER_PAGE);
    page = Math.max(1, Math.min(page, totalPages));   // #5: 범위 clamp
    curPage = page;
    var start = (page - 1) * PER_PAGE;
    var slice = all.slice(start, start + PER_PAGE);

    var cards = slice.map(function(p, i){
      var gi = start + i;
      var imgBlock = p.image
        ? '<img src="' + esc(p.image) + '" alt="' + esc(p.title) + '" loading="lazy" style="width:72px;height:72px;object-fit:cover;border-radius:6px;flex-shrink:0;display:block">'
        : '<div style="width:72px;height:72px;flex-shrink:0;border-radius:6px;background:linear-gradient(135deg,#154f7a,#1d89cf);display:flex;align-items:center;justify-content:center"><span style="color:#fff;font-size:22px">&#128196;</span></div>';
      return '<div style="' + S_CARD + '" data-card>'
        + '<span style="position:absolute;top:8px;left:8px;background:#0a2342;color:#fff;font-size:10px;font-weight:700;min-width:20px;height:20px;border-radius:10px;display:flex;align-items:center;justify-content:center;padding:0 5px;line-height:1;z-index:1">' + (gi+1) + '</span>'
        + '<div style="display:flex;align-items:flex-start;gap:12px;padding:14px 14px 10px">'
        + imgBlock
        + '<div style="font-size:13px;font-weight:700;line-height:1.5;color:#0a2342;flex:1">' + esc(p.title) + '</div>'
        + '</div>'
        + '<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 14px 12px;border-top:1px solid #e0eaf4">'
        + '<a href="' + esc(p.url) + '#comment-form" style="font-size:11px;color:#1d89cf;text-decoration:none;font-weight:600;letter-spacing:0.2px">&#128172; Post a Comment</a>'
        + '<a href="' + esc(p.url) + '" style="font-size:11px;color:#fff;background:#1d89cf;padding:4px 12px;border-radius:5px;text-decoration:none;font-weight:700;letter-spacing:0.4px">READ MORE</a>'
        + '</div>'
        + '</div>';
    }).join('');

    var startP = Math.max(1, Math.min(page - 2, totalPages - 4));
    var endP   = Math.min(totalPages, startP + 4);
    var pageBtns = '<button style="' + (page > 1 ? S_ON : S_OFF) + '" data-pg="' + (page-1) + '"' + (page > 1 ? '' : ' disabled') + '>&#8592; Prev</button>';
    for(var pg = startP; pg <= endP; pg++)
      pageBtns += '<button style="' + (pg === page ? S_ACT : S_ON) + '" data-pg="' + pg + '">' + pg + '</button>';
    pageBtns += '<button style="' + (page < totalPages ? S_ON : S_OFF) + '" data-pg="' + (page+1) + '"' + (page < totalPages ? '' : ' disabled') + '>Next &#8594;</button>';

    // #1: repeat(auto-fill) 으로 모바일 자동 대응
    contEl.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px;margin-bottom:14px">' + adCard + cards + '</div>'
      + '<div id="apl-pager" style="display:flex;align-items:center;justify-content:center;gap:6px;flex-wrap:wrap">'
      + pageBtns
      + '<span style="font-size:11px;color:#999">' + page + ' / ' + totalPages + '</span>'
      + '</div>';
    contEl.style.display = 'block';
    // ── Coupang carousel preview (iframe doc.write) ──────────
    (function(){
      var host = document.getElementById('cp-preview-host');
      if(!host) return;
      host.innerHTML = '';
      var ifrm = document.createElement('iframe');
      ifrm.style.cssText = 'width:100%;height:100%;border:none;pointer-events:none;display:block;';
      ifrm.setAttribute('scrolling','no');
      host.appendChild(ifrm);
      try {
        var d = ifrm.contentDocument || ifrm.contentWindow.document;
        d.open();
        d.write(
          '<html><body style="margin:0;padding:0;overflow:hidden;">'
          + '<sc'+'ript src="https://ads-partners.coupang.com/g.js"></sc'+'ript>'
          + '<sc'+'ript>new PartnersCoupang.G({id:476010,template:"carousel",trackingCode:"AF0526816",width:"600",height:"460"});</sc'+'ript>'
          + '</body></html>'
        );
        d.close();
      } catch(e) {}
    })();
  }

  function render(){
    if(loadEl) loadEl.style.display = 'none';
    var cntEl = document.getElementById('apl-count');
    if(cntEl) cntEl.textContent = all.length;
    if(!all.length){
      contEl.innerHTML = '<p style="color:#aaa;font-size:12px">No posts found.</p>';
      contEl.style.display = 'block';
      return;
    }
    renderPage(1);
  }

  // ── #7: 이벤트 위임 (window 전역 오염 제거) ──────────────
  contEl.addEventListener('click', function(ev){
    var btn = ev.target.closest && ev.target.closest('#apl-pager button:not([disabled])');
    if(!btn) return;
    var pg = parseInt(btn.getAttribute('data-pg'), 10);
    if(!pg) return;
    renderPage(pg);
    var wrap = document.getElementById('apl-wrap');
    if(wrap) wrap.scrollIntoView({behavior:'smooth', block:'start'});
  });
  contEl.addEventListener('mouseover', function(ev){
    var c = ev.target.closest && ev.target.closest('[data-card]');
    if(c){ c.style.background='#eef5fb'; c.style.boxShadow='0 3px 10px rgba(29,137,207,.15)'; }
  });
  contEl.addEventListener('mouseout', function(ev){
    var c = ev.target.closest && ev.target.closest('[data-card]');
    if(c){ c.style.background='#ffffff'; c.style.boxShadow='0 1px 4px rgba(0,0,0,.1)'; }
  });

  // ── #3: 캐시 히트 시 즉시 렌더, 미스 시 fetch ───────────
  var cached = loadCache();
  if(cached){ all = cached; render(); }
  else{ fetchPage(feedBase + '&max-results=50', 0); }
})();
//

function googleTranslateElementInit() {
  new google.translate.TranslateElement({
    pageLanguage: '',
    autoDisplay: 'true',
    layout: google.translate.TranslateElement.InlineLayout.
  }, 'google_translate_element');
}

body.script:
//
(function(){var el=document.getElementById('Stats1_totalCount');if(!el)return;var busy=false;var obs=new MutationObserver(function(){if(busy)return;var raw=(el.textContent||'').replace(/,/g,'').trim();var n=parseInt(raw,10);if(!isNaN(n)&&n>0){var f=n.toLocaleString('en-US');if(el.textContent.trim()!==f){busy=true;el.textContent=f;busy=false;}}});obs.observe(el,{childList:true,subtree:true,characterData:true});var content=document.getElementById('Stats1_content');if(content){var subObs=new MutationObserver(function(m,o){if(content.style.display!=='none'){o.disconnect();var sub=document.createElement('div');sub.className='stats1-sub';sub.textContent='All Time Visitors';content.appendChild(sub);var dot=document.createElement('div');dot.className='stats1-pulse';content.appendChild(dot);}});subObs.observe(content,{attributes:true,attributeFilter:['style']});}})();
//

//
(function () {
  "use strict";
  if (typeof THREE === "undefined") return;

  /* ── Visitor location (from Hello widget cache) ── */
  var lat = 35, lng = 139;
  try {
    var c = JSON.parse(
      localStorage.getItem("hg_ip_cache") ||
      localStorage.getItem("hg_ip_session") ||
      "null"
    );
    if (c && c.latitude != null) {
      lat = parseFloat(c.latitude);
      lng  = parseFloat(c.longitude);
    }
  } catch (e) {}

  /* ── Renderer ── */
  var canvas = document.getElementById("globe-canvas");
  var W = window.innerWidth, H = window.innerHeight;
  var renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true });
  renderer.setSize(W, H);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setClearColor(0x000005, 1);

  /* ── Label canvas (2-D overlay, DOM order above globe-canvas at same z-index) ── */
  var labelCanvas = document.getElementById('label-canvas');
  var lctx = labelCanvas.getContext('2d');
  var DPR = Math.min(window.devicePixelRatio, 2);
  labelCanvas.width  = W * DPR;
  labelCanvas.height = H * DPR;
  lctx.scale(DPR, DPR);

  var scene = new THREE.Scene();
  scene.background = new THREE.Color(0x000005);
  var camera = new THREE.PerspectiveCamera(42, W / H, 0.1, 100);
  camera.position.z = 2.3;

  /* ── Lighting ── */
  scene.add(new THREE.AmbientLight(0x112233, 1.5));
  var sun = new THREE.DirectionalLight(0xaaccee, 2.8);
  sun.position.set(5, 3, 4);
  scene.add(sun);

  /* ── Stars (3-layer depth) ── */
  function addStars(count, spread, size, color) {
    var buf = new Float32Array(count * 3);
    for (var i = 0; i < buf.length; i++) buf[i] = (Math.random() - 0.5) * spread;
    var geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.BufferAttribute(buf, 3));
    scene.add(new THREE.Points(geo, new THREE.PointsMaterial({ color: color, size: size, sizeAttenuation: true })));
  }
  addStars(2400, 80, 0.10, 0xffffff);   /* bright near stars */
  addStars(1800, 200, 0.07, 0xaaccff);  /* mid-field cool blue */
  addStars(1200, 400, 0.05, 0xffeedd);  /* distant warm stars */

  /* ── Earth sphere ── */
  var earthMat = new THREE.MeshPhongMaterial({ color: 0x4477aa, emissive: 0x061828, shininess: 14 });
  var earth = new THREE.Mesh(new THREE.SphereGeometry(1, 64, 64), earthMat);
  scene.add(earth);

  new THREE.TextureLoader().load(
    "https://cdn.jsdelivr.net/gh/mrdoob/three.js@r128/examples/textures/planets/earth_atmos_2048.jpg",
    function (tex) { earthMat.map = tex; earthMat.needsUpdate = true; }
  );

  /* ── Atmosphere glow ── */
  scene.add(new THREE.Mesh(
    new THREE.SphereGeometry(1.025, 48, 48),
    new THREE.MeshPhongMaterial({ color: 0x3399cc, transparent: true, opacity: 0.06, side: THREE.BackSide })
  ));

  /* ── lat/lng → 3-D point ── */
  function toVec3(la, ln, r) {
    var phi   = (90 - la) * Math.PI / 180;
    var theta = (ln + 180) * Math.PI / 180;
    return new THREE.Vector3(
      -r * Math.sin(phi) * Math.cos(theta),
       r * Math.cos(phi),
       r * Math.sin(phi) * Math.sin(theta)
    );
  }


  /* ── Visitor marker (gold pulsing sphere) ── */
  var vPos = toVec3(lat, lng, 1.018);
  var markerMesh = new THREE.Mesh(
    new THREE.SphereGeometry(0.014, 8, 8),
    new THREE.MeshBasicMaterial({ color: 0xffd700 })
  );
  markerMesh.position.copy(vPos);
  earth.add(markerMesh);

  /* ── Visitor glow ring ── */
  var ringMesh = new THREE.Mesh(
    new THREE.RingGeometry(0.022, 0.028, 20),
    new THREE.MeshBasicMaterial({ color: 0xffd700, transparent: true, opacity: 0.55, side: THREE.DoubleSide })
  );
  ringMesh.position.copy(vPos);
  ringMesh.lookAt(new THREE.Vector3(0, 0, 0));
  earth.add(ringMesh);

  /* ── Major Shipping Lanes ── */
  function gcPoints(wps, seg) {
    var pts = [];
    for (var i = 0; i < wps.length - 1; i++) {
      var a = toVec3(wps[i][0],   wps[i][1],   1.003).normalize();
      var b = toVec3(wps[i+1][0], wps[i+1][1], 1.003).normalize();
      for (var j = 0; j <= seg; j++) {
        pts.push(new THREE.Vector3().copy(a).lerp(b, j / seg).normalize().multiplyScalar(1.003));
      }
    }
    return pts;
  }
  function addLane(wps, col, opa) {
    var g = new THREE.BufferGeometry().setFromPoints(gcPoints(wps, 24));
    var m = new THREE.LineBasicMaterial({ color: col, transparent: true, opacity: opa });
    earth.add(new THREE.Line(g, m));
  }

  /* Asia–Europe (Suez) : Shanghai → Singapore → Colombo → Suez → Med → Rotterdam */
  addLane([[31,121],[22,114],[1,104],[5,80],[13,51],[30,32],[32,33],[37,28],[38,15],[37,5],[36,-5],[51,-3],[52,5]], 0x1affda, 0.55);
  /* Trans-Pacific : Shanghai → Tokyo → N.Pacific → Los Angeles */
  addLane([[31,121],[35,139],[42,155],[50,170],[52,-175],[48,-155],[40,-140],[34,-118]], 0x1affda, 0.55);
  /* Trans-Atlantic : Rotterdam → New York */
  addLane([[52,5],[50,-5],[46,-20],[43,-35],[40,-52],[38,-58],[41,-74]], 0x1affda, 0.55);
  /* Cape of Good Hope : Rotterdam → Cape Town → Singapore */
  addLane([[52,5],[36,-8],[20,-20],[0,-10],[-15,5],[-34,18],[-26,32],[-15,42],[0,45],[5,52],[1,104]], 0x7ec8f4, 0.38);
  /* Asia–Australia : Singapore → Sydney */
  addLane([[1,104],[-5,112],[-12,130],[-12,136],[-20,148],[-34,151]], 0x1affda, 0.45);
  /* Trans-Pacific South : Panama → Shanghai */
  addLane([[9,-80],[12,-105],[18,-135],[22,-155],[26,-175],[30,158],[31,130],[31,121]], 0x7ec8f4, 0.38);
  /* Indian Ocean : Mumbai → Durban */
  addLane([[19,73],[12,55],[0,48],[-10,42],[-20,38],[-30,32],[-34,18]], 0x7ec8f4, 0.38);
  /* Asia–East Africa : Singapore → Mombasa */
  addLane([[1,104],[0,80],[0,68],[-2,52],[0,43],[4,43]], 0x7ec8f4, 0.35);

  /* ── Initial position: visitor location centered immediately ── */
  var tY = -(lng * Math.PI / 180);
  var tX =  (lat * Math.PI / 180);
  earth.rotation.y = tY;
  earth.rotation.x = tX;
  var t0 = Date.now();
  var ANIM = 2500;
  var done = true;

  /* ── Satellites ── */
  var _PI = Math.PI;

  function satPos(r, incl, raan, ang) {
    var cx = r * Math.cos(ang), cz = r * Math.sin(ang);
    var y0 = cz * Math.sin(incl), z0 = cz * Math.cos(incl);
    return new THREE.Vector3(
      cx * Math.cos(raan) + z0 * Math.sin(raan),
      y0,
      -cx * Math.sin(raan) + z0 * Math.cos(raan)
    );
  }

  function orbitRing(r, incl, raan, col, opa) {
    var pts = [];
    for (var i = 0; i <= 128; i++) pts.push(satPos(r, incl, raan, (i / 128) * _PI * 2));
    var g = new THREE.BufferGeometry().setFromPoints(pts);
    scene.add(new THREE.Line(g, new THREE.LineBasicMaterial({ color: col, transparent: true, opacity: opa })));
  }

  var satList = [];
  function addSat(r, incl, raan, initAng, spd, col, sz, lbl, lclr) {
    var m = new THREE.Mesh(new THREE.SphereGeometry(sz, 4, 4), new THREE.MeshBasicMaterial({ color: col }));
    m.position.copy(satPos(r, incl, raan, initAng));
    scene.add(m);
    satList.push({ m: m, r: r, incl: incl, raan: raan, ang: initAng, spd: spd, lbl: lbl || null, lclr: lclr || '#ffffff' });
  }

  /* Starlink — 550 km LEO, incl 53°, 6 planes × 4 sats */
  var slR = 1.086, slI = 53 * _PI / 180, slS = 0.0006, slN = 0;
  for (var p = 0; p < 6; p++) {
    var ra = (p / 6) * _PI * 2;
    orbitRing(slR, slI, ra, 0x1a4466, 0.18);
    for (var s = 0; s < 4; s++) { slN++; addSat(slR, slI, ra, (s / 4) * _PI * 2, slS, 0x88ddff, 0.007, 'SL-' + (slN < 10 ? '0' + slN : '' + slN), '#7ec8f4'); }
  }

  /* GPS/GNSS — MEO scaled to 1.50, incl 55°, 3 planes × 4 sats */
  var gpR = 1.50, gpI = 55 * _PI / 180, gpS = 0.00014, gpN = 0;
  for (var p = 0; p < 3; p++) {
    var ra = (p / 3) * _PI * 2;
    orbitRing(gpR, gpI, ra, 0x1a4422, 0.14);
    for (var s = 0; s < 4; s++) { gpN++; addSat(gpR, gpI, ra, (s / 4) * _PI * 2, gpS, 0x44ff88, 0.009, 'GPS-' + (gpN < 10 ? '0' + gpN : '' + gpN), '#44ff88'); }
  }

  /* GEO — 35 786 km scaled to 1.88, near-equatorial, 5 sats */
  var geR = 1.88, geI = 2 * _PI / 180, geS = 0.00002;
  var GEO_NAMES = ['Inmarsat-4F3', 'Intelsat-19', 'SES-9', 'Eutelsat-5WB', 'Inmarsat-3F2'];
  orbitRing(geR, geI, 0, 0x442200, 0.14);
  for (var s = 0; s < 5; s++) addSat(geR, geI, 0, (s / 5) * _PI * 2, geS, 0xffaa44, 0.010, GEO_NAMES[s], '#ffaa44');

  /* ISS — 400 km, incl 51.6° */
  var isR = 1.063, isI = 51.6 * _PI / 180;
  orbitRing(isR, isI, _PI / 4, 0x553300, 0.20);
  addSat(isR, isI, _PI / 4, 0, 0.001, 0xffee44, 0.014, 'ISS', '#ffee44');

  /* reusable vector for "You are Here" projection (avoids per-frame allocation) */
  var _vWorld = new THREE.Vector3();

  /* ── Resize ── */
  window.addEventListener("resize", function () {
    W = window.innerWidth; H = window.innerHeight;
    camera.aspect = W / H;
    camera.updateProjectionMatrix();
    renderer.setSize(W, H);
    DPR = Math.min(window.devicePixelRatio, 2);
    labelCanvas.width  = W * DPR;
    labelCanvas.height = H * DPR;
    lctx.scale(DPR, DPR);
  });

  /* ── Interactive drag rotation ── */
  var _drag = { on: false, x: 0, y: 0, moved: false };

  function _ds(cx, cy) { _drag.on = true; _drag.x = cx; _drag.y = cy; _drag.moved = false; }
  function _dm(cx, cy) {
    if (!_drag.on) return;
    var dx = cx - _drag.x, dy = cy - _drag.y;
    if (!_drag.moved && Math.abs(dx) + Math.abs(dy) < 4) return;
    _drag.moved = true;
    earth.rotation.y += dx * 0.004;
    earth.rotation.x = Math.max(-1.4, Math.min(1.4, earth.rotation.x + dy * 0.004));
    _drag.x = cx; _drag.y = cy;
    document.body.style.cursor = 'grabbing';
  }
  function _de() {
    if (_drag.moved) document.body.style.cursor = '';
    _drag.on = false; _drag.moved = false;
  }

  window.addEventListener('mousedown', function(e) { _ds(e.clientX, e.clientY); });
  window.addEventListener('mousemove', function(e) { _dm(e.clientX, e.clientY); });
  window.addEventListener('mouseup', _de);
  window.addEventListener('touchstart', function(e) {
    if (e.touches.length === 1) _ds(e.touches[0].clientX, e.touches[0].clientY);
  }, { passive: true });
  window.addEventListener('touchmove', function(e) {
    if (e.touches.length === 1) _dm(e.touches[0].clientX, e.touches[0].clientY);
  }, { passive: true });
  window.addEventListener('touchend', _de);

  /* ── Zoom (left-button held + wheel) ── */
  window.addEventListener('wheel', function(e) {
    if (!_drag.on) return;
    camera.position.z = Math.max(1.3, Math.min(4.5, camera.position.z + e.deltaY * 0.003));
    e.preventDefault();
  }, { passive: false });

  /* ── Render loop ── */
  (function loop() {
    requestAnimationFrame(loop);
    var el = Date.now() - t0;
    if (!done) {
      var t = Math.min(el / ANIM, 1);
      var e = 1 - Math.pow(1 - t, 3); // cubic ease-out
      earth.rotation.y = tY * e;
      earth.rotation.x = tX * e;
      if (t >= 1) done = true;
    } else {
      if (!_drag.on) earth.rotation.y += 0.00007;
    }
    /* ── Update satellites + draw labels ── */
    lctx.clearRect(0, 0, W, H);
    for (var i = 0; i < satList.length; i++) {
      var sv = satList[i];
      sv.ang += sv.spd;
      sv.m.position.copy(satPos(sv.r, sv.incl, sv.raan, sv.ang));

      if (!sv.lbl) continue;
      /* front > 0 = near side of earth (camera.position is on +Z axis) */
      var front = sv.m.position.z / sv.r;
      if (front < 0.06) continue;
      var alpha = Math.min(1, (front - 0.06) / 0.20) * 0.90;

      var proj = sv.m.position.clone().project(camera);
      var sx = (proj.x * 0.5 + 0.5) * W;
      var sy = (-proj.y * 0.5 + 0.5) * H;

      var isISS = sv.lbl === 'ISS';
      lctx.font = (isISS ? 'bold 10px' : '8px') + ' Inter,sans-serif';
      var tw  = lctx.measureText(sv.lbl).width;
      var bx  = sx + 7, by = sy - 15;
      var bw  = tw + 6, bh = (isISS ? 13 : 11);

      lctx.globalAlpha = alpha;
      lctx.fillStyle = 'rgba(2,8,22,0.72)';
      lctx.fillRect(bx - 2, by, bw, bh);
      lctx.fillStyle = sv.lclr;
      lctx.fillText(sv.lbl, bx, by + bh - 2);
      lctx.globalAlpha = 1;
    }
    var pulse = 0.75 + 0.25 * Math.sin(Date.now() * 0.003);
    markerMesh.scale.setScalar(pulse);
    ringMesh.material.opacity = 0.3 + 0.25 * Math.sin(Date.now() * 0.002);

    /* ── "You are Here" label on visitor marker ── */
    markerMesh.getWorldPosition(_vWorld);
    var vFront = _vWorld.z / _vWorld.length();
    if (vFront > 0.05) {
      var vAlpha = Math.min(1, (vFront - 0.05) / 0.15) * 0.92;
      _vWorld.project(camera);
      var vx = (_vWorld.x * 0.5 + 0.5) * W;
      var vy = (-_vWorld.y * 0.5 + 0.5) * H;
      var vlbl = 'You are Here';
      lctx.font = 'bold 10px Inter,sans-serif';
      var vtw = lctx.measureText(vlbl).width;
      var vbx = vx + 12, vby = vy - 20;
      var vbw = vtw + 10, vbh = 14;
      lctx.globalAlpha = vAlpha;
      lctx.fillStyle = 'rgba(2,8,22,0.82)';
      lctx.fillRect(vbx - 2, vby, vbw, vbh);
      lctx.strokeStyle = 'rgba(255,215,0,0.75)';
      lctx.lineWidth = 1;
      lctx.beginPath();
      lctx.moveTo(vx, vy);
      lctx.lineTo(vbx, vby + vbh * 0.5);
      lctx.stroke();
      lctx.fillStyle = '#ffd700';
      lctx.fillText(vlbl, vbx + 2, vby + vbh - 2);
      lctx.globalAlpha = 1;
    }

    renderer.render(scene, camera);
  })();
})();
//

//
  /* ── Right panel master toggle (hamburger) ── */
  function rpMasterToggle() {
    var rp = document.getElementById('right-panel');
    var btn = document.getElementById('rp-master-btn');
    var isMobile = window.innerWidth <= 1024;
    if (isMobile) {
      var open = rp.classList.toggle('rp-mobile-open');
      btn.textContent = open ? '×' : '☰';
      try { localStorage.setItem('rp_mobile_open', open ? '1' : '0'); } catch(e) {}
    } else {
      var collapsed = rp.classList.toggle('rp-collapsed');
      btn.textContent = collapsed ? '☰' : '×';
      try { localStorage.setItem('rp_collapsed', collapsed ? '1' : '0'); } catch(e) {}
    }
  }
  (function() {
    function initPanel() {
      var rp = document.getElementById('right-panel');
      var btn = document.getElementById('rp-master-btn');
      if (!rp || !btn) return;
      var isMobile = window.innerWidth <= 1024;
      if (isMobile) {
        try {
          if (localStorage.getItem('rp_mobile_open') === '1') {
            rp.classList.add('rp-mobile-open');
            btn.textContent = '×';
          } else {
            btn.textContent = '☰';
          }
        } catch(e) { btn.textContent = '☰'; }
      } else {
        try {
          if (localStorage.getItem('rp_collapsed') === '1') {
            rp.classList.add('rp-collapsed');
            btn.textContent = '☰';
          } else {
            btn.textContent = '×';
          }
        } catch(e) { btn.textContent = '×'; }
      }
    }
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', initPanel);
    } else {
      initPanel();
    }
  })();

  /* ── Right panel widget 최소화 / 원래대로 ── */
  function rpToggle(cardId, btn) {
    var card = document.getElementById(cardId);
    var minimized = card.classList.toggle('minimized');
    btn.textContent = minimized ? '+' : '—';
    try { localStorage.setItem('rp_min_' + cardId, minimized ? '1' : '0'); } catch(e) {}
  }
  (function() {
    ['rp-card-weather', 'rp-card-hello', 'rp-card-insights', 'rp-card-services'].forEach(function(id) {
      try {
        if (localStorage.getItem('rp_min_' + id) === '1') {
          var card = document.getElementById(id);
          if (card) {
            card.classList.add('minimized');
            var btn = card.querySelector('.rp-btn');
            if (btn) btn.textContent = '+';
          }
        }
      } catch(e) {}
    });
  })();

  /* ── Sidebar widget 최소화 / 원래대로 ── */
  function sbToggle(widgetId, btn) {
    var widget = document.getElementById(widgetId);
    var minimized = widget.classList.toggle('minimized');
    btn.textContent = minimized ? '+' : '—';
    try { localStorage.setItem('sb_min_' + widgetId, minimized ? '1' : '0'); } catch(e) {}
  }
  (function() {
    var configs = [
      { id: 'Label4', icon: '📌', title: 'TOPICAL POSTS' },
      { id: 'HTML10', icon: '🧭', title: 'MARITIME INTELLIGENCE' }
    ];
    function initCard(cfg) {
      var widget = document.getElementById(cfg.id);
      if (!widget) return;
      /* 기존 자식 전체를 .sb-body 로 이동 */
      var body = document.createElement('div');
      body.className = 'sb-body';
      while (widget.firstChild) body.appendChild(widget.firstChild);
      /* 헤더 생성 */
      var head = document.createElement('div');
      head.className = 'sb-head';
      head.innerHTML = '<span class="sb-head-title">' + cfg.icon + ' ' + cfg.title + '</span>'
        + '<button class="sb-btn" onclick="sbToggle(\'' + cfg.id + '\',this)">—</button>';
      widget.appendChild(head);
      widget.appendChild(body);
      widget.classList.add('sb-collapsible');
      /* 저장된 최소화 상태 복원 */
      try {
        if (localStorage.getItem('sb_min_' + cfg.id) === '1') {
          widget.classList.add('minimized');
          head.querySelector('.sb-btn').textContent = '+';
        }
      } catch(e) {}
    }
    function runInit() { configs.forEach(initCard); }
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', runInit);
    } else {
      runInit();
    }
  })();

  /* ── Main content widget 최소화 / 원래대로 ── */
  function mcToggle(widgetId, btn) {
    var widget = document.getElementById(widgetId);
    var minimized = widget.classList.toggle('minimized');
    btn.textContent = minimized ? '+' : '—';
    try { localStorage.setItem('mc_min_' + widgetId, minimized ? '1' : '0'); } catch(e) {}
  }
  (function() {
    var configs = [
      { id: 'HTML7', icon: '🔥', title: 'Featured Insights' },
      { id: 'HTML8', icon: '🛠️', title: 'LIVE FEED Service' }
    ];
    function initMcCard(cfg) {
      var widget = document.getElementById(cfg.id);
      if (!widget) return;
      /* 기존 section 내부 header div 에 버튼 삽입 */
      var section = widget.querySelector('section');
      if (!section) return;
      var hdrDiv = section.querySelector('div');
      if (!hdrDiv) return;
      hdrDiv.style.cssText += ';display:flex;justify-content:space-between;align-items:flex-start;';
      var btn = document.createElement('button');
      btn.className = 'mc-btn';
      btn.textContent = '—';
      var wid = cfg.id;
      btn.onclick = function() { mcToggle(wid, this); };
      hdrDiv.appendChild(btn);
      widget.classList.add('mc-collapsible');
      try {
        var saved = localStorage.getItem('mc_min_' + cfg.id);
        if (saved !== '0') {
          widget.classList.add('minimized');
          btn.textContent = '+';
        }
      } catch(e) {
        widget.classList.add('minimized');
        btn.textContent = '+';
      }
    }
    function runInit() { configs.forEach(initMcCard); }
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', runInit);
    } else {
      runInit();
    }
  })();

  /* ── Move Hello Guest widget to right panel ── */
  (function(){
    var target = document.getElementById('hg-right');
    if (!target) return;
    function move() {
      var wrap = document.getElementById('hg-wrap');
      if (wrap && !target.contains(wrap)) {
        target.appendChild(wrap);
        return true;
      }
      return false;
    }
    if (!move()) {
      var obs = new MutationObserver(function() {
        if (move()) obs.disconnect();
      });
      obs.observe(document.body, { childList: true, subtree: true });
    }
  })();

  /* ── Right panel top — 데스크톱: 실제 헤더 높이 기준 배치 ── */
  (function(){
    var rp = document.getElementById('right-panel');
    if (!rp) return;
    function setPanelTop() {
      if (window.innerWidth <= 1024) return; /* 모바일은 별도 처리 */
      var hdr = document.querySelector('.centered-top-container');
      if (!hdr) return;
      var h = hdr.getBoundingClientRect().height;
      if (h > 10) rp.style.top = (h + 12) + 'px';
    }
    if (document.readyState === 'complete') {
      setTimeout(setPanelTop, 200);
    } else {
      window.addEventListener('load', function(){ setTimeout(setPanelTop, 200); });
    }
    window.addEventListener('resize', setPanelTop);
  })();

  /* ── Maritime Weather Widget ── */
  (function(){
    var el = document.getElementById('mw-widget');
    if (!el) return;

    /* 위치: Hello Widget 캐시 우선, 없으면 기본(서울) */
    var lat = 37.5, lng = 127.0, city = '';
    try {
      var c = JSON.parse(localStorage.getItem('hg_ip_cache') || 'null');
      if (c && c.latitude != null) {
        lat  = parseFloat(c.latitude);
        lng  = parseFloat(c.longitude);
        city = [c.city, c.country_code].filter(Boolean).join(', ');
      }
    } catch(e) {}

    /* Beaufort 변환 (km/h) */
    function bft(k) {
      var b=[1,6,12,20,29,39,50,62,75,89,103,118];
      for(var i=0;i<b.length;i++) if(k<b[i]) return i;
      return 12;
    }
    /* 풍향 16방위 */
    function cmp(d) {
      var dirs=['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
      return dirs[Math.round(d/22.5)%16];
    }
    /* WMO 날씨 아이콘 */
    function wicon(code) {
      if(code===0)       return '☀️';
      if(code<=2)        return '⛅';
      if(code===3)       return '☁️';
      if(code<=48)       return '🌫️';
      if(code<=67)       return '🌧️';
      if(code<=77)       return '🌨️';
      if(code<=82)       return '🌦️';
      if(code<=86)       return '🌨️';
      return '⛈️';
    }
    /* 더글라스 해상 상태 */
    function seaState(h) {
      if(h==null)  return '—';
      if(h<0.1)    return 'Glassy (0)';
      if(h<0.5)    return 'Rippled (1)';
      if(h<1.25)   return 'Slight (3)';
      if(h<2.5)    return 'Moderate (4)';
      if(h<4.0)    return 'Rough (5)';
      if(h<6.0)    return 'Very Rough (6)';
      if(h<9.0)    return 'High (7)';
      return 'Very High (8)';
    }

    var wURL = 'https://api.open-meteo.com/v1/forecast?latitude='+lat+'&longitude='+lng
      +'&current=temperature_2m,weather_code,wind_speed_10m,wind_direction_10m,'
      +'surface_pressure,visibility,precipitation&wind_speed_unit=kmh&timezone=auto';
    var mURL = 'https://marine-api.open-meteo.com/v1/marine?latitude='+lat+'&longitude='+lng
      +'&current=wave_height,wave_direction,wave_period,swell_wave_height,swell_wave_direction,swell_wave_period';

    Promise.all([
      fetch(wURL).then(function(r){return r.json();}),
      fetch(mURL).then(function(r){return r.json();}).catch(function(){return null;})
    ]).then(function(res){
      var w  = res[0].current;
      var m  = res[1] && res[1].current;

      var temp = Math.round(w.temperature_2m);
      var wind = Math.round(w.wind_speed_10m);
      var wdir = w.wind_direction_10m;
      var pres = Math.round(w.surface_pressure);
      var vis  = w.visibility != null ? (w.visibility/1000).toFixed(1) : '—';
      var bf   = bft(wind);
      var ic   = wicon(w.weather_code);

      var waveH  = m && m.wave_height    != null ? (+m.wave_height).toFixed(1)    : null;
      var waveP  = m && m.wave_period    != null ? (+m.wave_period).toFixed(0)    : null;
      var waveD  = m && m.wave_direction != null ? cmp(m.wave_direction)           : null;
      var swH    = m && m.swell_wave_height   != null ? (+m.swell_wave_height).toFixed(1)   : null;
      var swD    = m && m.swell_wave_direction!= null ? cmp(m.swell_wave_direction)          : null;
      var swP    = m && m.swell_wave_period   != null ? (+m.swell_wave_period).toFixed(0)   : null;

      var h = '<div class="mw-hdr">'+ ic +' Maritime Wx'
            + (city?'<span class="mw-city">📍'+city+'</span>':'')+'</div>'
            + '<div class="mw-row"><span>🌡 '+ temp +'°C</span><span>📊 '+ pres +' hPa</span></div>'
            + '<div class="mw-row"><span>💨 Bft <b>'+ bf +'</b> '+ cmp(wdir) +' '+ wind +'km/h</span>'
            +   '<span>👁 '+ vis +'km</span></div>'
            + '<hr class="mw-hr"/>';

      if (waveH) {
        h += '<div class="mw-row"><span>🌊 Wave '+ waveH +'m '+(waveD||'')+'/'+(waveP||'—')+'s</span>'
           + '<span class="mw-sea">'+ seaState(parseFloat(waveH)) +'</span></div>';
        if (swH) {
          h += '<div class="mw-row"><span>↗ Swell '+ swH +'m '+(swD||'')+'/'+(swP||'—')+'s</span></div>';
        }
      } else {
        h += '<div class="mw-nomarine">⚓ Inland — no marine data</div>';
      }
      el.innerHTML = h;
    }).catch(function(){
      el.innerHTML = '<span style="color:rgba(200,228,248,0.5)">Weather unavailable</span>';
    });
  })();
  //
